#include "SoundLibrary.h"
static void testSoundLibrary(const File& root,Assets& assets){
    auto file=root.getChildFile("personal-sound-checks.json");file.deleteFile();SoundLibrary library;expect(loadSoundLibrary(file,library).wasOk()&&library.personal.empty()&&library.favorites.isEmpty(),"absent sound library starts empty without creating a file");expect(!file.exists(),"reading an absent sound library has no disk mutation");
    std::set<String> factoryIds;for(const auto& p:factorySynthPresets())factoryIds.insert(factorySoundId(p));expect(factoryIds.size()==72,"factory sound identities are stable and unique across engines");
    PersonalSound entry{"user-first",factorySynthPresets()[7]};entry.sound.name=String::fromUTF8("Мой звук");entry.sound.category="Personal leads";entry.sound.patch.cutoff=2345;
    expect(putPersonalSound(file,entry).wasOk(),"new named sound saves into local personal library");expect(loadSoundLibrary(file,library).wasOk()&&library.personal.size()==1&&library.personal[0].sound.name==entry.sound.name&&library.personal[0].sound.patch==entry.sound.patch,"sound library roundtrip retains Unicode and every synth parameter");auto before=file.loadFileAsString();
    expect(putPersonalSound(file,entry).failed()&&file.loadFileAsString()==before,"existing personal identity requires explicit update");auto duplicate=entry;duplicate.id="user-second";expect(putPersonalSound(file,duplicate).failed()&&file.loadFileAsString()==before,"duplicate sound name in one engine is rejected atomically");
    duplicate.sound.instrument=Instrument::fm;expect(putPersonalSound(file,duplicate).wasOk(),"different engines may share a personal sound name");duplicate.sound.name="UPPERCASE";duplicate.id="user-third";expect(putPersonalSound(file,duplicate).wasOk(),"distinct personal sound name is stored");auto collision=duplicate;collision.id="user-fourth";collision.sound.name="uppercase";before=file.loadFileAsString();expect(putPersonalSound(file,collision).failed()&&file.loadFileAsString()==before,"personal sound names are unique ignoring case within an engine");
    auto factoryId=factorySoundId(factorySynthPresets()[0]);expect(setSoundFavorite(file,factoryId,true).wasOk()&&setSoundFavorite(file,entry.id,true).wasOk(),"factory and personal sounds can both be favorites");loadSoundLibrary(file,library);expect(library.favorites.contains(factoryId)&&library.favorites.contains(entry.id),"favorite identities survive library reload");auto token=soundLibraryToken(file);expect(setSoundFavorite(file,entry.id,true).wasOk()&&soundLibraryToken(file)==token,"repeated favorite request is idempotent");
    entry.sound.name="Renamed voice";entry.sound.category="Custom";entry.sound.patch.lfoPitch=14;expect(putPersonalSound(file,entry,true).wasOk()&&loadSoundLibrary(file,library).wasOk()&&library.favorites.contains(entry.id)&&findPersonalSound(library,entry.id)->sound.name==entry.sound.name,"rename and category change retain favorite identity");
    entry.sound.instrument=Instrument::fm;entry.sound.patch.fmRatio=3.5f;expect(putPersonalSound(file,entry,true).wasOk()&&loadSoundLibrary(file,library).wasOk()&&findPersonalSound(library,entry.id)->sound.instrument==Instrument::fm&&library.favorites.contains(entry.id),"explicit update can store another engine while retaining identity and favorites");
    SynthPreset resolved;expect(resolveLibrarySound(library,entry.id,resolved)&&resolved.patch==entry.sound.patch,"personal recall resolves complete stored patch");expect(resolveLibrarySound(library,factoryId,resolved)&&resolved.name==factorySynthPresets()[0].name,"factory favorite resolves original built-in sound");auto previous=resolved;expect(!resolveLibrarySound(library,"missing",resolved)&&resolved.patch==previous.patch,"missing library sound leaves recall output intact");
    auto stale=soundLibraryToken(file);expect(setSoundFavorite(file,factoryId,false).wasOk(),"favorite removal updates library");before=file.loadFileAsString();entry.sound.patch.cutoff=3456;expect(putPersonalSound(file,entry,true,stale).failed()&&file.loadFileAsString()==before,"stale update token cannot overwrite a newer favorite edit");expect(removePersonalSound(file,entry.id,stale).failed()&&file.loadFileAsString()==before,"stale delete token preserves the library");expect(setSoundFavorite(file,entry.id,false,stale).failed()&&file.loadFileAsString()==before,"stale favorite token preserves latest settings");
    auto unknown=entry;unknown.id="user-missing";expect(putPersonalSound(file,unknown,true).failed()&&file.loadFileAsString()==before,"updating a deleted identity never silently recreates it");expect(setSoundFavorite(file,"unknown-factory",true).failed()&&file.loadFileAsString()==before,"favorite cannot reference unavailable sound");
    auto exported=root.getChildFile("library-export.pulsesound");loadSoundLibrary(file,library);auto stored=*findPersonalSound(library,entry.id);expect(saveSynthPreset(stored.sound,exported).wasOk(),"personal stored settings export through the single-sound format");SynthPreset imported;expect(loadSynthPreset(exported,imported).wasOk()&&imported.patch==stored.sound.patch,"relocated sound file imports complete settings");auto importedEntry=PersonalSound{"user-imported",imported};importedEntry.sound.name="Imported copy";expect(putPersonalSound(file,importedEntry).wasOk(),"imported copy receives independent personal identity");
    auto song=emptyProject();song.bpm=120;song.loop=false;song.tracks[7].instrument=stored.sound.instrument;song.tracks[7].synth=stored.sound.patch;song.tracks[7].soundName=stored.sound.name;song.tracks[7].attack=stored.sound.attack;song.tracks[7].release=stored.sound.release;song.tracks[7].send=0;song.patterns[0].lanes[7]={{0,.5,60,.8f}};auto originalAudio=render(song,assets,root,30000,127);auto projectBefore=JSON::toString(projectToJson(song));
    expect(removePersonalSound(file,stored.id).wasOk()&&loadSoundLibrary(file,library).wasOk()&&!findPersonalSound(library,stored.id)&&!library.favorites.contains(stored.id),"delete removes personal entry and its favorite reference");auto remainingAudio=render(song,assets,root,30000,512);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<30000;++i)same&=originalAudio.getSample(ch,i)==remainingAudio.getSample(ch,i);expect(same&&originalAudio.getMagnitude(0,0,30000)>.001f&&JSON::toString(projectToJson(song))==projectBefore,"deleting library source preserves embedded project sound and identical audio");
    before=file.loadFileAsString();expect(removePersonalSound(file,stored.id).failed()&&file.loadFileAsString()==before,"repeated missing-source deletion preserves remaining entries");
    auto parsed=soundLibraryToJson(library);SoundLibrary parsedLibrary;expect(soundLibraryFromJson(parsed,parsedLibrary).wasOk()&&JSON::toString(soundLibraryToJson(parsedLibrary))==JSON::toString(parsed),"whole sound library roundtrips exactly");auto sentinel=parsedLibrary;parsed.getDynamicObject()->setProperty("schema",99);expect(soundLibraryFromJson(parsed,parsedLibrary).failed()&&JSON::toString(soundLibraryToJson(parsedLibrary))==JSON::toString(soundLibraryToJson(sentinel)),"future library schema preserves existing output");
    parsed=soundLibraryToJson(library);parsed["personal"].getArray()->add((*parsed["personal"].getArray())[0]);expect(soundLibraryFromJson(parsed,parsedLibrary).failed(),"duplicate personal IDs rejected on load");parsed=soundLibraryToJson(library);parsed["favorites"].getArray()->add("orphan");expect(soundLibraryFromJson(parsed,parsedLibrary).failed(),"orphaned favorites rejected on load");
    auto bad=entry;bad.id="factory-user";expect(putPersonalSound(file,bad).failed()&&file.loadFileAsString()==before,"personal identities cannot impersonate factory identities");bad=entry;bad.id="user-new";bad.sound.name=" Bad ";expect(putPersonalSound(file,bad).failed()&&file.loadFileAsString()==before,"surrounding name whitespace rejected");bad.sound.name="Bad\nname";expect(putPersonalSound(file,bad).failed()&&file.loadFileAsString()==before,"control characters rejected in sound metadata");bad.sound.name="Too long category";bad.sound.category=String::repeatedString("x",41);expect(putPersonalSound(file,bad).failed()&&file.loadFileAsString()==before,"oversized category rejected atomically");bad.sound.category="User";bad.sound.patch.cutoff=std::numeric_limits<float>::quiet_NaN();expect(putPersonalSound(file,bad).failed()&&file.loadFileAsString()==before,"non-finite patch data cannot enter personal library");
    auto corrupt=root.getChildFile("corrupt-sound-library.json");corrupt.replaceWithText("{not valid JSON");auto corruptBefore=corrupt.loadFileAsString();expect(loadSoundLibrary(corrupt,parsedLibrary).failed()&&JSON::toString(soundLibraryToJson(parsedLibrary))==JSON::toString(soundLibraryToJson(sentinel)),"corrupt JSON leaves caller library intact");expect(putPersonalSound(corrupt,entry).failed()&&removePersonalSound(corrupt,"user-first").failed()&&setSoundFavorite(corrupt,factoryId,true).failed()&&saveSoundLibrary(corrupt,{}).failed()&&corrupt.loadFileAsString()==corruptBefore,"all mutations preserve a corrupt library instead of resetting it");
    auto oversized=root.getChildFile("oversized-sound-library.json");oversized.replaceWithText(String::repeatedString("x",maxSoundLibraryBytes+1));expect(loadSoundLibrary(oversized,parsedLibrary).failed()&&soundLibraryToken(oversized)=="oversized","oversized libraries are rejected before parsing/hash allocation");
    SoundLibrary full;for(int i=0;i<maxPersonalSounds;++i){PersonalSound p{"user-"+String(i),factorySynthPresets()[i%40]};p.sound.name="Patch "+String(i);full.personal.push_back(p);}auto capacityFile=root.getChildFile("full-sound-library.json");capacityFile.deleteFile();expect(saveSoundLibrary(capacityFile,full).wasOk()&&loadSoundLibrary(capacityFile,library).wasOk()&&library.personal.size()==128,"full 128-sound library saves and reloads");before=capacityFile.loadFileAsString();entry.id="user-overflow";expect(putPersonalSound(capacityFile,entry).failed()&&capacityFile.loadFileAsString()==before,"129th sound is rejected without partial write");auto replacement=full.personal[0];replacement.sound.patch.cutoff=777;expect(putPersonalSound(capacityFile,replacement,true).wasOk(),"explicit update remains available at full capacity");
    auto blocked=root.getChildFile("blocked-sound-directory");blocked.replaceWithText("not a directory");expect(putPersonalSound(blocked.getChildFile("library.json"),entry).failed()&&blocked.loadFileAsString()=="not a directory","disk-directory failure preserves existing data");
}
